package com.foodflow.delivery.entity;import com.fasterxml.jackson.annotation.JsonIgnore;import jakarta.persistence.*;import lombok.*;import java.time.Instant;import java.util.UUID;@Entity @Table(name="deliveries",uniqueConstraints=@UniqueConstraint(columnNames="order_id")) @Getter @Setter @NoArgsConstructor public class Delivery{@Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id;@Column(name="order_id",nullable=false,unique=true) private UUID orderId;@Column(name="partner_id",nullable=false) private UUID partnerId;@Column(nullable=false) private String status="ASSIGNED";@Column(name="payment_method",nullable=false,length=32) private String paymentMethod="RAZORPAY";@JsonIgnore @Column(name="delivery_address",length=500) private String deliveryAddress;@Column(name="cash_collected_at") private Instant cashCollectedAt;@Column(nullable=false) private Instant assignedAt=Instant.now();}
